/// <summary>
/// Computes the loyalty discount applied to an order subtotal: a tier base rate plus an
/// order-size bonus, capped at 10 percentage points, applied to the original subtotal and
/// rounded down to a whole cent.
/// </summary>
public static class LoyaltyDiscount
{
    private const decimal MaxRatePoints = 10m;

    public static decimal For(LoyaltyTier tier, decimal subtotal)
    {
        var rate = EffectiveRatePoints(tier, subtotal) / 100m;

        return decimal.Floor(subtotal * rate * 100m) / 100m;
    }

    private static decimal EffectiveRatePoints(LoyaltyTier tier, decimal subtotal)
    {
        var rate = BaseRatePoints(tier) + OrderSizeBonusPoints(subtotal);

        return Math.Min(rate, MaxRatePoints);
    }

